/** Dedicated N01 adapter over the original076 invocation ledger. Historical facts never
 * mint a current model token. Every context derives from an actual registered exact input. */
public final class TaskPlanDraftInvocationRecords {
 private final JdbcTemplate db;private final TaskPlanDraftInvocationObjects objects;private final FormalInvocationSchema schema;private final PermissionSchema json;private final TaskPlanDraftProducerAuthority producers;
 public TaskPlanDraftInvocationRecords(DataSource data,TaskPlanDraftInvocationObjects objects,FormalInvocationSchema schema,PermissionSchema json,TaskPlanDraftProducerAuthority producers){db=new JdbcTemplate(data);db.setQueryTimeout(5);this.objects=objects;this.schema=schema;this.json=json;this.producers=producers;}
 public Registered register(TaskPlanDraftInvocationContext.Prepared p,TaskPlanDraftInvocationObjects.Registered exact)throws Exception {
  p.requireUnchanged();exact.requireUnchanged();if(!exact.receipt().required("provenance").equals(p.provenance())||!Arrays.equals(p.bytes(),exact.bytes()))bad();var j=p.authority().job();var deps=(ObjectNode)p.provenance();deps.put("exact_input_artifact_id",exact.artifactId()).put("exact_input_receipt_sha256",schema.hash(exact.receipt()));deps.set("exact_input_receipt",exact.receipt());
  String id=UUID.nameUUIDFromBytes(("PLAN_DRAFT_CONTEXT/"+p.sessionId()+"/"+p.requestId()+"/"+p.requestSha256()).getBytes(StandardCharsets.US_ASCII)).toString();
  String range=ObjectContentPaging.rangeDigest(ObjectContentPaging.objectDigest(exact.reference()),0,Long.parseLong(exact.reference().sizeBytes()));var request=json.object().put("schema_version","1.0.0").put("execution_kind","SYSTEM_JOB").put("job_type","PLAN_DRAFT").put("node_kind","N01").put("model_config_revision",text(deps.required("model"),"model_config_revision")).put("business_purpose",text(deps,"business_purpose")).put("maximum_input_tokens",text(deps,"maximum_input_tokens"));
  request.set("exact_input",json.tree(new CommonProtocol.ArtifactRef(exact.artifactId(),exact.reference().sha256(),TaskPlanDraftInvocationSchema.EXACT_INPUT_REF,new CommonProtocol.Coverage(range,range,true,null))));
  for(String key:List.of("enterprise_budget_basis","parent_budget_basis","request_parameters"))request.set(key,deps.required(key));request.set("prompt_basis",deps.required("prompt_compilation").required("prompt_basis"));request.set("tokenizer_basis",deps.required("tokenizer_version"));
  var source=json.object().put("execution_kind","SYSTEM_JOB").put("job_type","PLAN_DRAFT").put("node_kind","N01");source.set("request",request);source.set("dependencies",deps);
  var document=document(id,source,exact.accessSetId());String digest=schema.hash(document);var previous=db.queryForList("SELECT context_manifest_id FROM context_manifest WHERE tenant_id=? AND context_manifest_id=? LIMIT 2 FOR UPDATE",j.tenant(),id);
  if(previous.isEmpty()){
   var now=one(db.query("SELECT UTC_TIMESTAMP(6)",(r,n)->r.getTimestamp(1).toLocalDateTime()));changed(db.update("INSERT INTO version_registry(tenant_id,version_id,owner_project_id,entity_kind,content_sha256) VALUES(?,?,?,'CONTEXT_MANIFEST',?)",j.tenant(),id,j.project(),digest));
   changed(db.update("INSERT INTO context_manifest(tenant_id,project_id,context_manifest_id,exact_input_ref,source_manifest,prompt_revision,tokenizer_revision,token_count,dependency_access_set_id,content_sha256,execution_mode,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,?,?,?,?,?,?,'EXTERNAL','1.0.0',?,?,?,?)",j.tenant(),j.project(),id,schema.canonical(request.required("exact_input")),schema.canonical(source),text(request.required("prompt_basis"),"version_id"),text(request.required("tokenizer_basis"),"version_id"),text(deps.required("tokenization"),"token_count"),exact.accessSetId(),digest,schema.manifestSha256(),j.actor(),now,j.classification()));
   changed(db.update("INSERT INTO audit_event(tenant_id,project_id,audit_id,subject_id,action,resource_ref,result,request_id,trace_id,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,'task.plan_draft.context.registered',?,'SUCCESS',?,?,'1.0.0',?,?,?,?)",j.tenant(),j.project(),UUID.randomUUID().toString(),j.actor(),schema.canonical(document),id,j.run(),schema.manifestSha256(),j.actor(),now,j.classification()));
   changed(db.update("INSERT INTO outbox_event(tenant_id,event_id,aggregate_id,aggregate_revision,event_type,payload,occurred_at) VALUES(?,?,?,1,'task.plan_draft.context.registered',?,?)",j.tenant(),id,id,schema.canonical(document),now));
  }
  var result=requireStored(j.tenant(),id);if(!source.equals(result.source))bad();return result;
 }
 public final class Registered {
  private final String id,access;private final JsonNode source;private final byte[] bytes;
  private Registered(String id,String access,JsonNode source,byte[] bytes){this.id=id;this.access=access;this.source=source.deepCopy();this.bytes=bytes.clone();}
  public void requireUnchanged()throws Exception {var fresh=requireStored(text(dependencies(),"tenant_id"),id);if(!source.equals(fresh.source)||!access.equals(fresh.access)||!Arrays.equals(bytes,fresh.bytes))bad();}
  public String contextId(){return id;}public String accessSetId(){return access;}public JsonNode request(){return source.required("request").deepCopy();}public JsonNode dependencies(){return source.required("dependencies").deepCopy();}public byte[] bytes(){return bytes.clone();}
 }
 Registered requireStored(String tenant,String context)throws Exception {
  currentTenant(tenant);WireValues.uuid(context);var row=one(db.queryForList("SELECT * FROM context_manifest WHERE tenant_id=? AND context_manifest_id=? LIMIT 2",tenant,context));var source=schema.parse(str(row,"source_manifest"));if(!"SYSTEM_JOB".equals(text(source,"execution_kind"))||!"PLAN_DRAFT".equals(text(source,"job_type"))||!"N01".equals(text(source,"node_kind")))bad();var deps=source.required("dependencies");var request=source.required("request");String access=str(row,"dependency_access_set_id");
  var exact=objects.requireStored(tenant,text(deps,"exact_input_artifact_id"));if(!schema.hash(exact.receipt()).equals(text(deps,"exact_input_receipt_sha256"))||!exact.receipt().equals(deps.required("exact_input_receipt"))||!access.equals(exact.accessSetId()))bad();
  var original=(ObjectNode)deps.deepCopy();original.remove(List.of("exact_input_artifact_id","exact_input_receipt_sha256","exact_input_receipt"));if(!original.equals(exact.receipt().required("provenance")))bad();same(tenant,text(deps,"tenant_id"));same(str(row,"project_id"),text(deps,"project_id"));same(str(row,"created_by"),text(deps,"actor_id"));same(str(row,"classification"),text(deps,"classification"));same("EXTERNAL",str(row,"execution_mode"));same(schema.manifestSha256(),str(row,"schema_manifest_sha256"));same(schema.canonical(request.required("exact_input")),str(row,"exact_input_ref"));same(text(request.required("prompt_basis"),"version_id"),str(row,"prompt_revision"));same(text(request.required("tokenizer_basis"),"version_id"),str(row,"tokenizer_revision"));same(text(deps.required("tokenization"),"token_count"),str(row,"token_count"));
  same(exact.artifactId(),text(request.required("exact_input"),"artifact_id"));same(exact.reference().sha256(),text(request.required("exact_input"),"sha256"));same(text(deps,"payload_sha256"),WireValues.sha256(exact.bytes()));
  var document=document(context,source,access);same(schema.hash(document),str(row,"content_sha256"));same(schema.hash(document),one(db.query("SELECT content_sha256 FROM version_registry WHERE tenant_id=? AND version_id=? AND owner_project_id=? AND entity_kind='CONTEXT_MANIFEST' LIMIT 2",(r,n)->r.getString(1),tenant,context,text(deps,"project_id"))));
  same(document,schema.parse(one(db.query("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND project_id=? AND subject_id=? AND created_by=? AND action='task.plan_draft.context.registered' AND result='SUCCESS' AND reason_code IS NULL AND request_id=? AND trace_id=? AND created_at=? AND classification=? AND schema_manifest_sha256=? LIMIT 2",(r,n)->r.getString(1),tenant,text(deps,"project_id"),text(deps,"actor_id"),text(deps,"actor_id"),context,text(deps,"run_id"),row.get("created_at"),text(deps,"classification"),schema.manifestSha256()))));
  same(document,schema.parse(one(db.query("SELECT payload FROM outbox_event WHERE tenant_id=? AND event_id=? AND aggregate_id=? AND aggregate_revision=1 AND event_type='task.plan_draft.context.registered' AND occurred_at=? LIMIT 2",(r,n)->r.getString(1),tenant,context,context,row.get("created_at")))));
  // The private exact producer journal preserves the authenticated supervisor receipt.
  var observed=deps.required("model_request");same(text(deps,"session_id"),text(observed,"session_id"));same(deps.required("host_binding"),observed.required("binding"));same(text(deps,"supervision_receipt_id"),text(observed,"supervision_receipt_id"));same(text(deps,"supervision_sha256"),text(observed,"supervision_sha256"));
  byte[] projection=Base64.getDecoder().decode(text(observed,"body_base64"));same(WireValues.sha256(projection),text(observed,"body_sha256"));same(WireValues.sha256(projection),text(observed,"raw_body_sha256"));var projectionSchema=new TaskPlanDraftInvocationSchema();same(projectionSchema.sha256(),text(observed,"projection_schema_sha256"));var parsedProjection=projectionSchema.readProjection(projection);
  var systems=new ArrayList<String>();for(var system:deps.required("approved_system_messages")){if(!system.isTextual())bad();systems.add(system.textValue());}
  var replay=TaskInvocationProjection.planDraftInitial(parsedProjection,text(deps,"session_id"),text(deps,"launch_prompt"),systems,parsedProjection.required("tools"));same(replay,schema.parse(new String(exact.bytes(),StandardCharsets.UTF_8)));
  return new Registered(context,access,source,exact.bytes());
 }
 static final class Binding implements FormalInvocationBinding {
  private final Registered original;private final String action,request,requestHash,dependencies,dependenciesHash;
  private Binding(Registered original,String action,FormalInvocationSchema schema)throws Exception {this.original=original;WireValues.uuid(action);this.action=action;request=schema.canonical(original.request());requestHash=schema.hash(original.request());dependencies=schema.canonical(original.dependencies());dependenciesHash=schema.hash(original.dependencies());}
  private JsonNode node(){return original.dependencies();}public String tenant(){return text(node(),"tenant_id");}public String project(){return text(node(),"project_id");}public String actor(){return text(node(),"actor_id");}public String run(){return text(node(),"run_id");}public String principal(){return text(node(),"principal_id");}public String step(){return text(node(),"step_id");}public String action(){return action;}public String context(){return original.id;}public String inputHash(){return text(node(),"input_sha256");}public String model(){return text(original.request(),"model_config_revision");}public String verification(){return text(node().required("model_eligibility"),"connection_verification_id");}public String classification(){return text(node(),"classification");}public String request(){return request;}public String requestHash(){return requestHash;}public String dependencies(){return dependencies;}public String dependenciesHash(){return dependenciesHash;}public String generation(){return text(node(),"lease_generation");}public String session(){return text(node(),"session_id");}public String taskId(){return text(node(),"task_id");}Registered original(){return original;}
  JsonNode snapshot(){return new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode().put("execution_kind","SYSTEM_JOB").put("job_type","PLAN_DRAFT").put("node_kind","N01").put("context_manifest_id",context()).put("action_id",action);}
 }
 Binding bind(Registered context,String action)throws Exception {context.requireUnchanged();return new Binding(context,action,schema);}
 boolean supports(String tenant,String run){var rows=db.query("SELECT run_id FROM system_job_run WHERE tenant_id=? AND run_id=? AND execution_kind='SYSTEM_JOB' AND job_type='PLAN_DRAFT' LIMIT 2",(r,n)->r.getString(1),tenant,run);if(rows.size()>1)bad();return rows.size()==1;}
 Binding byInvocation(String tenant,String invocation)throws Exception {
  currentTenant(tenant);var row=one(db.queryForList("SELECT i.*,b.canonical_request,b.request_sha256,b.authorization_snapshot,b.authorization_sha256 FROM invocation i JOIN formal_invocation_binding b ON b.tenant_id=i.tenant_id AND b.invocation_id=i.invocation_id JOIN system_job_run j ON j.tenant_id=i.tenant_id AND j.run_id=i.run_id AND j.execution_kind='SYSTEM_JOB' AND j.job_type='PLAN_DRAFT' WHERE i.tenant_id=? AND i.invocation_id=? LIMIT 2",tenant,invocation));var result=new Binding(requireStored(tenant,str(row,"context_manifest_id")),str(row,"action_id"),schema);var auth=schema.parse(str(row,"authorization_snapshot"));same(schema.hash(auth),str(row,"authorization_sha256"));same(result.snapshot(),auth.required("plan_draft_binding"));same(result.request,str(row,"canonical_request"));same(result.requestHash,str(row,"request_sha256"));same(result.dependenciesHash,text(auth,"job_dependency_sha256"));same(result.verification(),text(auth,"verification_id"));same(result.generation(),text(auth,"lease_generation"));
  for(var p:Map.of("project_id",result.project(),"run_id",result.run(),"step_id",result.step(),"created_by",result.actor(),"input_sha256",result.inputHash(),"config_revision",result.model(),"verification_id",result.verification(),"classification",result.classification(),"lease_generation",result.generation()).entrySet())same(p.getValue(),str(row,p.getKey()));
  if(one(db.query("SELECT COUNT(*) FROM step_action_binding WHERE tenant_id=? AND run_id=? AND step_id=? AND action_id=? AND invocation_id=? AND kind='MODEL_CALL' AND input_sha256=? AND arguments_sha256=? AND tool_version=? AND lease_generation=?",(r,n)->r.getInt(1),tenant,result.run(),result.step(),result.action(),invocation,result.inputHash(),result.requestHash(),result.model(),result.generation()))!=1)bad();return result;
 }
 List<ArtifactRegistryProtocol.MemberRow> contentMembers(Binding b)throws Exception {b.original.requireUnchanged();var result=new ArrayList<ArtifactRegistryProtocol.MemberRow>();for(var m:b.original.dependencies().required("content_members"))result.add(new ArtifactRegistryProtocol.MemberRow(text(m,"upstream_version_id"),text(m,"rights_revision")));return List.copyOf(result);}
 void requireOutput(Binding b,String kind,byte[] bytes)throws Exception {b.original.requireUnchanged();if(!Set.of("MODEL_RESULT","PROVIDER_CAPTURE").contains(kind))bad();if(bytes.length==0||bytes.length>TaskPlanDraftInvocationSchema.MAXIMUM_BYTES)bad();var payload=schema.parse(new String(bytes,StandardCharsets.UTF_8));if("MODEL_RESULT".equals(kind)){if(!b.context().equals(text(payload,"context_manifest_id"))||!b.model().equals(text(payload,"model_config_revision")))bad();}}
 void requireProduction(Binding b,FormalInvocationOutcomeAuthority.VerifiedOutcome outcome,String kind,byte[] bytes)throws Exception {
  outcome.requireActive();producers.requireOriginalOutput(outcome,b.original.dependencies().required("producer"),kind,bytes.length);requireOutput(b,kind,bytes);if(!b.tenant().equals(outcome.tenantId())||!b.actor().equals(outcome.actorId())||!b.run().equals(text(outcome.binding(),"run_id"))||!b.action().equals(text(outcome.binding(),"action_id")))bad();
  var authorization=schema.parse(one(db.query("SELECT authorization_snapshot FROM formal_invocation_binding WHERE tenant_id=? AND invocation_id=? LIMIT 2",(r,n)->r.getString(1),b.tenant(),outcome.invocationId())));var c=authorization.required("plan_draft_output_commitment");
  if(!"SYSTEM_JOB".equals(text(c,"execution_kind"))||!"PLAN_DRAFT".equals(text(c,"job_type"))||!"N01".equals(text(c,"node_kind"))||!outcome.invocationId().equals(text(c,"invocation_id"))||!b.context().equals(text(c,"context_manifest_id"))||!b.inputHash().equals(text(c,"input_sha256"))||c.required("maximum_bytes").intValue()!=TaskPlanDraftInvocationSchema.MAXIMUM_BYTES||bytes.length>c.required("maximum_bytes").intValue())bad();
  if(!c.required("producer").equals(b.original.dependencies().required("producer")))bad();
  if(!c.required("storage").equals(b.original.dependencies().required("output_storage"))||!c.required("output_retention").equals(b.original.dependencies().required("output_retention")))bad();
  var created=one(db.query("SELECT created_at FROM system_job_run WHERE tenant_id=? AND project_id=? AND run_id=? AND job_type='PLAN_DRAFT' AND execution_kind='SYSTEM_JOB'",(r,n)->r.getTimestamp(1).toInstant(),b.tenant(),b.project(),b.run()));TaskInvocationOutputPolicy.requireOriginal(c.required("output_retention"),b.run(),created,b.original.dependencies().required("retention"));
 }
 void requireRecoveryPolicy(Binding b,FormalInvocationOutcomeAuthority.VerifiedOutcome outcome,RuntimeObjectTransport transport)throws Exception {
  requireProduction(b,outcome,"MODEL_RESULT",outcome.bytes());if(!json.tree(transport.storageBinding()).equals(b.original.dependencies().required("output_storage")))throw new TenantAccessException(ErrorCode.SCOPE_STALE);
 }
 private JsonNode document(String context,JsonNode source,String access){var n=json.object().put("schema_version","1.0.0").put("context_manifest_id",context).put("dependency_access_set_id",access).put("execution_mode","EXTERNAL");n.set("source_manifest",source);return n;}
 private static void currentTenant(String tenant){if(!org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()||!tenant.equals(TenantScope.requireCurrent().tenantId()))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}private static String text(JsonNode n,String k){if(!n.required(k).isTextual())bad();return n.required(k).textValue();}private static String str(Map<String,Object> r,String k){if(r.get(k)==null)bad();return r.get(k).toString();}private static void same(Object a,Object b){if(!Objects.equals(a,b))bad();}private static <T>T one(List<T> rows){if(rows.size()!=1)bad();return rows.get(0);}private static void changed(int n){if(n!=1)throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
